/**
 * The hidden WebView that runs the E2EE engine. Mount it once, at the app root, before
 * anything signs in - it boots in the background (1-3 s on a slow phone: wasm compile and
 * the store open) and every encrypted send, decrypt and key operation waits for it.
 *
 * It renders nothing visible and takes no input. The page it loads is generated by
 * crypto-host/build.mjs; the protocol, lifecycle and failure modes are in ./README.md.
 *
 * Crash handling: when the WebView's process dies (iOS content-process termination,
 * Android renderer gone - both happen to background apps under memory pressure), every call
 * in flight fails, the client invalidates the old page's machine handles, this component
 * mounts a fresh WebView, and the machine layer reopens the store once the new page is
 * ready. If it keeps dying (MAX_CRASHES in host.ts) it stays down rather than looping.
 */
import { useEffect, useRef, useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { WebView, type WebViewMessageEvent } from 'react-native-webview';
import type { ShouldStartLoadRequest } from 'react-native-webview/lib/WebViewTypes';
import { HOST_HTML } from '../../../assets/crypto/hostPage';
import { cryptoHost, scheduleCryptoStorageWipe, takeCryptoStorageWipe } from './host';
import { HOST_ORIGIN } from './protocol';
import { loadEngineWasmBase64 } from './wasmAsset';

const SOURCE = { html: HOST_HTML, baseUrl: `${HOST_ORIGIN}/` };

/** Our page's URL, however the platform spells it (Android drops the trailing slash). */
function fromHost(url: string | undefined): boolean {
  return typeof url === 'string' && (url === HOST_ORIGIN || url.startsWith(`${HOST_ORIGIN}/`));
}

export function CryptoHost() {
  const ref = useRef<WebView>(null);
  // A new key mounts a new WebView (and a new page) after a crash.
  const [life, setLife] = useState(0);

  // One transport for the component's life: it posts to whichever WebView is current, so a
  // remounted page's hello finds the client already attached and simply boots again.
  useEffect(
    () =>
      cryptoHost.attach(
        {
          post(message) {
            const view = ref.current;
            if (!view) throw new Error('crypto host WebView is not mounted');
            view.postMessage(message);
          },
        },
        {
          loadWasmBase64: loadEngineWasmBase64,
          takeWipe: takeCryptoStorageWipe,
          restoreWipe: scheduleCryptoStorageWipe,
        },
      ),
    [],
  );

  const restart = (reason: string) => {
    if (cryptoHost.crashed(reason)) setLife((n) => n + 1);
  };

  const onMessage = (ev: WebViewMessageEvent) => {
    // Only the page we loaded speaks the protocol; navigation elsewhere is refused below.
    if (!fromHost(ev.nativeEvent.url)) return;
    cryptoHost.receive(ev.nativeEvent.data);
  };

  // The page never navigates. Anything else (a link, a redirect, a script setting location)
  // is refused, so the only document this WebView ever runs is ours.
  const onShouldStartLoadWithRequest = (req: ShouldStartLoadRequest) =>
    fromHost(req.url) || req.url === 'about:blank';

  return (
    <View style={styles.hidden} pointerEvents="none" accessibilityElementsHidden importantForAccessibility="no-hide-descendants">
      <WebView
        key={life}
        ref={ref}
        source={SOURCE}
        originWhitelist={[`${HOST_ORIGIN}/*`, 'about:blank']}
        onMessage={onMessage}
        onShouldStartLoadWithRequest={onShouldStartLoadWithRequest}
        onContentProcessDidTerminate={() => restart('content process terminated')}
        onRenderProcessGone={(e) => restart(e.nativeEvent.didCrash ? 'renderer crashed' : 'renderer killed by the system')}
        // Persistent, ordinary storage: the store must outlive the app process.
        incognito={false}
        cacheEnabled
        domStorageEnabled
        javaScriptEnabled
        // Nothing to load, nothing to share, nothing to open.
        allowFileAccess={false}
        allowFileAccessFromFileURLs={false}
        allowUniversalAccessFromFileURLs={false}
        setSupportMultipleWindows={false}
        javaScriptCanOpenWindowsAutomatically={false}
        thirdPartyCookiesEnabled={false}
        sharedCookiesEnabled={false}
        mixedContentMode="never"
        geolocationEnabled={false}
        textInteractionEnabled={false}
        scrollEnabled={false}
        webviewDebuggingEnabled={__DEV__}
        style={styles.webview}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  // In the window (iOS suspends a WKWebView that is not), but one transparent pixel that
  // nothing can touch or read.
  hidden: { position: 'absolute', top: 0, left: 0, width: 1, height: 1, opacity: 0, overflow: 'hidden' },
  webview: { width: 1, height: 1, backgroundColor: 'transparent' },
});
